// v16.xx (rvw2), the CLOUD REVIEW of 2026-10-15, finding 6 (checked against the code): the world marks of the events were drawn on the screen over walls and the fog: the ring and the name of the bounty pillager (BOUNTY $1,500)
// and the convoy and the Overseer ring followed the body wherever it stood, so a pillager behind a wall or in the dark was pointed out to the pixel, and the coolant glints sat on every rich crate, seen or not. The game's rule
// is line of sight. The ring and the name of a body now draw only while that body is SEEN (the same flag the body itself is drawn by, a teammate's sight counts); the event stays a pinned mark with its name on the minimap and
// the sector map, which is where it is announced. The coolant glints draw on the crates you can see.
function evUnseen(ev){
  var b=null, d=ev.d;
  if(!d) return false;
  if(ev.id==='bounty') b=d.e; else if(ev.id==='convoy') b=d.car; else if(ev.id==='rampage') b=d.b;
  return !!b&&b.hp>0&&!b.seen;
}
// FLOW-MODULE-END (the next flow builds add their code above this line)

